// Service worker: offline mode for the app shell.
// Replaces the deprecated Application Cache (offline.appcache).
//
// Generated by EmitSwPlugin (webpack.config.js); version comes from package.json.
// All urls are relative and resolve against this file's location,
// so the app works under any subpath (deployed at /ril/app/).

const VERSION = '0.12.02a'
const CACHE_NAME = 'ril-' + VERSION

const PRECACHE_URLS = [
  // App shell document. Keyed as the scope root ('./' -> e.g. '/ril/app/')
  // so it matches navigation requests offline.
  './',
  './app.js',
  './vendor/lodash.js',
  './vendor/quo.debug.js',
  './css/ionicons-2.0.1/css/ionicons.min.css',
  './css/ionicons-2.0.1/fonts/ionicons.eot?v=2.0.0',
  './css/ionicons-2.0.1/fonts/ionicons.svg?v=2.0.0',
  './css/ionicons-2.0.1/fonts/ionicons.ttf?v=2.0.0',
  './css/ionicons-2.0.1/fonts/ionicons.woff?v=2.0.0',
  './i/icon.png',
  './i/tldr.png',
]

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(CACHE_NAME)
      .then((cache) => cache.addAll(PRECACHE_URLS))
      // Take over immediately, same as the old appcache 'swapCache'.
      .then(() => self.skipWaiting())
  )
})

self.addEventListener('activate', (event) => {
  // Drop caches of all previous versions (keeps iOS storage in check).
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(
          keys
            .filter((key) => key !== CACHE_NAME)
            .map((key) => caches.delete(key))
        )
      )
      .then(() => self.clients.claim())
  )
})

self.addEventListener('fetch', (event) => {
  const request = event.request
  if (request.method !== 'GET') return

  const url = new URL(request.url)

  // App document: network-first (always fresh when online),
  // cached shell when offline.
  if (request.mode === 'navigate') {
    event.respondWith(
      fetch(request)
        .then((response) => {
          const copy = response.clone()
          if (response.ok) {
            caches.open(CACHE_NAME).then((cache) => cache.put('./', copy))
          }
          return response
        })
        .catch(() =>
          caches.match(request).then((cached) => cached || caches.match('./'))
        )
    )
    return
  }

  // Google fonts css: stale-while-revalidate.
  // Responses are cross-origin opaque (status 0), cached as-is.
  if (url.hostname === 'fonts.googleapis.com') {
    event.respondWith(
      caches.open(CACHE_NAME).then((cache) =>
        cache.match(request).then((cached) => {
          const refresh = fetch(request)
            .then((response) => {
              cache.put(request, response.clone())
              return response
            })
            .catch(() => cached)
          return cached || refresh
        })
      )
    )
    return
  }

  // Font files: cache-first (opaque responses, cached as-is).
  if (url.hostname === 'fonts.gstatic.com' || url.pathname.endsWith('.woff2')) {
    event.respondWith(
      caches.open(CACHE_NAME).then((cache) =>
        cache.match(request).then(
          (cached) =>
            cached ||
            fetch(request).then((response) => {
              cache.put(request, response.clone())
              return response
            })
        )
      )
    )
    return
  }

  // Same-origin app assets: cache-first.
  if (url.origin === self.location.origin) {
    event.respondWith(
      caches.match(request).then((cached) => cached || fetch(request))
    )
    return
  }

  // Everything else: network only (appcache 'NETWORK: *' equivalent).
})